                case '\\': sb.append('\\'); break;
                default: sb.append('\\').append(c); break;
            }
            nextIsEscape = false;
        } else if (c == '\\') {
            nextIsEscape = true;
        } else {
            sb.append(c);
        }
    }
    if (nextIsEscape) {
