private List<Pair<Integer,Integer>> computeEdgeSeparators(Graph<E> graph, E edge) {
    List<Pair<Integer,Integer>> separators = new ArrayList<>();
    for (int vertex : graph.getVertices()) {
        if (graph.hasEdge(vertex, edge)) {
            List<Integer> neighbors = graph.getNeighbors(vertex);
            List<Integer> separator = findSeparator(neighbors, edge);
            separators.add(new Pair<>(separator, vertex));
        }
    }
    return separators;
}

private List<Integer> findSeparator(List<Integer> neighbors, E edge) {
    List<Integer> separator = new ArrayList<>();
    for (Integer neighbor : neighbors) {
        if (!graph.hasEdge(neighbor, edge)) {
            separator.add(neighbor);
        }
    }
    return separator;
}

