int function(byte[] buffer, int bufferIndex) throws IOException {
    if (bufferIndex >= buffer.length) {
        return 0; // EOF
    }

    int firstByte = buffer[bufferIndex++] & 0xFF;
    if ((firstByte & 0x80) == 0) {
        return firstByte;
    }

    int tag = firstByte & 0x7F;
    while ((firstByte & 0x80) != 0) {
        if (bufferIndex >= buffer.length) {
            throw new IOException("Protocol message contained a tag with invalid wire type");
        }
        firstByte = buffer[bufferIndex++] & 0xFF;
        tag = ((tag << 7) | (firstByte & 0x7F));
    }

    return tag;
}
